const r = await api.get("/mails", { label: "complaint" });
const items = r.items || [];
const out = [];
for (const m of items) {
  if (m.customer_id) {
    const c = await api.get(`/customers/${m.customer_id}`);
    out.push({ mail_id: m.id, from: m.from_name, subject: m.subject, customer_id: m.customer_id, name: c.name, tier: c.tier });
  } else {
    out.push({ mail_id: m.id, from: m.from_name, subject: m.subject, customer_id: null, note: "고객 연결 없음" });
  }
}
console.log(JSON.stringify({ count: r.count, items: out }, null, 2));

